+          swizzle128_offset((r % kWgRows) * 4u + tt, lane * 4u);
+      ptx::st_shared(
+          reinterpret_cast<uint32_t*>(lin_base + off),
+          static_cast<uint32_t>(c01) | (static_cast<uint32_t>(c23) << 16));
+    }
+    if (lane == 0) sm.lin_scale[r] = s;
+  }
